import{_ as t,c as e,o,N as a,az as n,aA as s}from"./chunks/framework.HSbrZY_1.js";const _=JSON.parse('{"title":"How to add custom networks","description":"","frontmatter":{"title":"How to add custom networks","order":12,"outline":[0,4]},"headers":[],"relativePath":"products/ultra-wallet/custom-networks.md","filePath":"products/ultra-wallet/custom-networks.md","lastUpdated":null}'),r={name:"products/ultra-wallet/custom-networks.md"},l=a('<h1 id="how-to-add-custom-networks" tabindex="-1">How to add custom networks <a class="header-anchor" href="#how-to-add-custom-networks" aria-label="Permalink to &quot;How to add custom networks&quot;">​</a></h1><p>Besides the built-in <strong>Mainnet</strong> and <strong>Testnet</strong>, you can add your own networks to the Ultra Wallet extension, for example a local development node.</p><ol><li><p>Open the Ultra Wallet extension and click the network name under your account (or open the <strong>Menu</strong>, top right, and select <strong>Networks</strong>).</p><p><img src="'+n+'" alt="Networks screen"></p></li><li><p>Click <strong>Add Custom Network</strong>, enter a <strong>Network Name</strong> and the <strong>Node URL</strong> of your Ultra node (see <a href="./../../blockchain/general/tools/nodeos.html">nodeos</a>), then click <strong>Add Network</strong>.</p><p><img src="'+s+'" alt="Add Custom Network form"></p></li><li><p>Select a network in the list to switch to it. Custom networks can also be edited or deleted from this screen.</p></li></ol><p>The wallet checks a network before saving it:</p><ul><li>The Node URL must use <strong>HTTPS</strong>. <code>http://localhost</code> and <code>http://127.0.0.1</code> are allowed for local development.</li><li>Private and internal network addresses are refused.</li><li>The name must not imitate a built-in network (for example &quot;Ultra Mainnet&quot;).</li><li>The wallet contacts the node and records its chain ID.</li></ul><div class="info custom-block"><p class="custom-block-title">Websites cannot add networks</p><p>Only you can add a network, on this screen. Websites cannot add networks to your wallet. A connected website can switch the wallet to a network you have already added (extension 2.2.14+). See <a href="./../ultra-wallet-sdk/accounts-and-networks.html#adding-a-network">Ultra Wallet SDK → Accounts &amp; Networks</a>.</p></div>',6),d=[l];function c(i,u,w,p,m,h){return o(),e("div",null,d)}const g=t(r,[["render",c]]);export{_ as __pageData,g as default};
